installer-gui-script.script:
function installedVersion() {
  var plist = system.files.plistAtPath(system.env.HOME + '/Applications/Cascade.app/Contents/Info.plist');
  if (!plist) return null;
  var v = plist.CFBundleShortVersionString;
  if (!v || (v == '1.0.0' && plist.CFBundleVersion == '1')) return null;
  return v;
}
function checkVersion() {
  var have = installedVersion();
  if (!have) return true;
  var c = system.compareVersions(have, '@VERSION@');
  if (c > 0) {
    my.result.type = 'Fatal';
    my.result.title = 'A newer Cascade is installed';
    my.result.message = 'Cascade ' + have + ' is installed and this package is @VERSION@. Downgrades are not supported. To go back anyway, run ~/Library/Application Support/cascade/bin/uninstall first.';
    return false;
  }
  if (c == 0) {
    my.result.type = 'Warn';
    my.result.title = 'Cascade @VERSION@ is already installed';
    my.result.message = 'Continuing reinstalls it. Settings, the browser pairing and downloads are kept.';
    return false;
  }
  return true;
}
